@WebServlet("/hitung")
class HitungServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        HttpSession sesi = req.getSession();
        Integer n = (Integer) sesi.getAttribute("kunjungan");
        n = n == null ? 1 : n + 1;
        sesi.setAttribute("kunjungan", n);
        res.setContentType("text/plain;charset=UTF-8");
        res.getWriter().print("Kunjungan ke-" + n);
    }
}

