import java.io.*;
import java.util.*;

import jakarta.servlet.*;
import jakarta.servlet.annotation.*;
import jakarta.servlet.http.*;
import com.bisangoding.web.*;

public class Main {
    public static void main(String[] args) {
        ServerUji server = new ServerUji();
        server.tambah(new KeranjangServlet());
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(" ");
            if (d[0].equals("ganti-pengguna")) {
                server.lupakanCookie();
            } else if (d[0].equals("beli")) {
                server.kirim("POST", "/keranjang", "barang=" + d[1]);
            } else {
                System.out.println(server.kirim("GET", "/keranjang").isi());
            }
        }
    }
}

@WebServlet("/keranjang")
class KeranjangServlet extends HttpServlet {
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse res) throws IOException {
        isiKeranjang(req).add(req.getParameter("barang"));
        res.sendRedirect("/keranjang");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        res.setContentType("text/plain;charset=UTF-8");
        res.getWriter().print("Keranjang: " + isiKeranjang(req));
    }

    @SuppressWarnings("unchecked")
    private List<String> isiKeranjang(HttpServletRequest req) {
        HttpSession sesi = req.getSession();
        List<String> isi = (List<String>) sesi.getAttribute("isi");
        if (isi == null) {
            isi = new ArrayList<>();
            sesi.setAttribute("isi", isi);
        }
        return isi;
    }
}
